
(function() {
  function b64ToF32(b64) {
    var bin = atob(b64);
    var len = bin.length;
    var bytes = new Uint8Array(len);
    for (var i = 0; i < len; i++) {
      bytes[i] = bin.charCodeAt(i);
    }
    return new Float32Array(bytes.buffer);
  }
  window.GLOBE_DATA = {
    getEdgePoints: function() { return b64ToF32(""); },
    getFillPoints: function() { return b64ToF32(""); }
  };
})();
